export function initDiscount({ onQuote }) {
    const input = document.getElementById("discount-code");
    const button = document.getElementById("apply-discount");
    const error = document.getElementById("discount-error");

    async function apply() {
        error.textContent = "";
        button.disabled = true;
        try {
            const response = await fetch("/api/checkout", {
                method: "POST",
                headers: { "content-type": "application/json" },
                body: JSON.stringify({ code: input.value }),
            });
            const body = await response.json();
            if (!response.ok) {
                error.textContent = body.error ?? "Could not apply code";
                return;
            }
            if (body.code) input.value = body.code;
            onQuote(body);
        } catch {
            error.textContent = "Could not apply code";
        } finally {
            button.disabled = false;
        }
    }

    button.addEventListener("click", apply);
    input.addEventListener("keydown", (event) => {
        if (event.key === "Enter") apply();
    });
}
