export class DiscountError extends Error {}

const codes = {
    SAVE20: ({ subtotal_cents }) => ({ discount_cents: Math.round(subtotal_cents * 0.2) }),
    FREESHIP: () => ({ shipping_cents: 0 }),
    BULK3: ({ items }) => ({
        discount_cents: items.reduce(
            (sum, item) => sum + (item.quantity >= 3 ? Math.min(300, item.price_cents) * item.quantity : 0),
            0,
        ),
    }),
};
const expired = new Set(["SUMMER10"]);

// Returns null for no/blank code, otherwise the normalised upper-case code.
export function normaliseCode(raw) {
    if (raw === undefined || raw === null) return null;
    const code = String(raw).trim().toUpperCase();
    return code === "" ? null : code;
}

// Returns { code, discount_cents, shipping_cents } or throws DiscountError.
export function applyCode(raw, { items, subtotal_cents, shipping_cents }) {
    const code = normaliseCode(raw);
    const result = { code, discount_cents: 0, shipping_cents };
    if (code === null) return result;
    if (expired.has(code)) throw new DiscountError(`${code} has expired`);
    if (!Object.hasOwn(codes, code)) throw new DiscountError(`${code} is not a valid code`);
    Object.assign(result, codes[code]({ items, subtotal_cents, shipping_cents }));
    result.discount_cents = Math.min(result.discount_cents, subtotal_cents);
    return result;
}
