export function render(quote) {
    document.getElementById("items").innerHTML = quote.items.map((item) => `
        <div class="item">
          <div class="thumb">${item.name[0]}</div>
          <div class="name">${item.name}<small>Qty ${item.quantity}</small></div>
          <div class="price">${money(item.price_cents * item.quantity)}</div>
        </div>`).join("");
    document.getElementById("subtotal").textContent = money(quote.subtotal_cents);
    document.getElementById("discount-label").textContent = quote.code ? `Discount (${quote.code})` : "Discount";
    document.getElementById("discount").textContent =
        quote.discount_cents > 0 ? `-${money(quote.discount_cents)}` : money(0);
    document.getElementById("shipping").textContent = money(quote.shipping_cents);
    document.getElementById("total").textContent = money(quote.total_cents);
}

const error_box = document.getElementById("discount-error");

function showError(message) {
    error_box.textContent = message ?? "";
    error_box.hidden = !message;
}

async function applyDiscount() {
    const button = document.getElementById("apply-discount");
    button.disabled = true;
    try {
        const response = await fetch("/api/checkout", {
            method: "POST",
            headers: { "content-type": "application/json" },
            body: JSON.stringify({ code: document.getElementById("discount-code").value }),
        });
        const body = await response.json();
        if (!response.ok) return showError(body.error ?? "Could not apply that code");
        showError(null);
        render(body);
    } catch {
        showError("Could not apply that code. Please try again.");
    } finally {
        button.disabled = false;
    }
}

document.getElementById("discount-form").addEventListener("submit", (event) => {
    event.preventDefault();
    applyDiscount();
});

const response = await fetch("/api/cart");
render(await response.json());

new EventSource("/__reload").onmessage = (event) => {
    if (event.data === "reload") location.reload();
};
